select stt.id as session_ticket_type_id, stt.ticket_type_id, tt.name as ticket_type_name, stt.sale_price, stt.allocated_quantity, stt.remaining_quantity, stt.status from admission_session s join session_ticket_type stt on stt.session_id = s.id join ticket_type tt on tt.id = stt.ticket_type_id where s.id = #{sessionId} and s.status = 'OPEN' and s.booking_start_at <= CURRENT_TIMESTAMP and s.booking_end_at > CURRENT_TIMESTAMP and stt.status = 'ON_SALE' and stt.remaining_quantity > 0 and stt.id in
#{id}
order by stt.id

mapper.update:
update session_ticket_type
set remaining_quantity = remaining_quantity - #{quantity},
    updated_at = CURRENT_TIMESTAMP
where id = #{sessionTicketTypeId}
  and session_id = #{sessionId}
  and status = 'ON_SALE'
  and remaining_quantity >= #{quantity}

update session_ticket_type
set remaining_quantity = remaining_quantity + #{quantity},
    updated_at = CURRENT_TIMESTAMP
where id = #{sessionTicketTypeId}
  and session_id = #{sessionId}
  and remaining_quantity + #{quantity} <= allocated_quantity

