mapper.update:
update admission_session
set status = #{targetStatus},
    updated_at = CURRENT_TIMESTAMP
where id = #{id}
  and venue_id = #{venueId}
  and status = #{currentStatus}

mapper.delete:
delete from admission_session
where id = #{id}
  and venue_id = #{venueId}
  and status = 'DRAFT'
